/// ReconcileResponse is the edits that make the files say what the
/// source says; a file already saying it needs none.
#[derive(Clone, PartialEq, ::prost::Message)]
pub struct ReconcileResponse {
    /// Edits are applied in order, each over the file as the one before
    /// left it.
    #[prost(message, repeated, tag = "1")]
    pub edits: ::prost::alloc::vec::Vec<Edit>,
}
/// Edit sets a sequence of strings at a key path of one document of a
/// file; with no values, it removes the key. The path is a manifest of
